        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Patient Health Questionnaire (PHQ-9)",
              "description": "The change in the total PHQ-9 score between baseline and 4-weeks follow-up is the primary outcome measure. This measure is a patient-rated inventory of depressive symptoms. All items are scored on scales ranging from 0-3 and the sum of the scores provides the total score for the measure. On this scale, higher scores indicate poorer outcomes. Scores 9-19 and 20-27 are considered moderate and severe depression respectively.",
              "timeFrame": "Baseline and 4 weeks"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Patient Health Questionnaire (PHQ-9)",
              "description": "The change in the total PHQ-9 score between baseline, and the intermediate 2-weeks, and 4-weeks follow-up is the secondary outcome measures. This measure is a patient-rated inventory of depressive symptoms. All items are scored on scales ranging from 0-3 and the sum of the scores provides the total score for the measure. On this scale, higher scores indicate poorer outcomes. Scores 9-19 and 20-27 are considered moderate and severe depression respectively.",
