              "timeFrame": "Baseline, 2-weeks, and 4-weeks follow up"
            },
            {
              "measure": "Depressive symptoms remission",
              "description": "Remission rate of Major Depression in the two groups over the course of treatment, defining remission as a score ≤ 4 on the PHQ-9 scale.",
              "timeFrame": "Baseline, 2 weeks, 4 weeks"
            }
          ]
